package lk.villagecraft.auth;
import lk.villagecraft.users.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/admin/staff") public class AdminStaffController {private final AppUserRepository users;private final PasswordEncoder encoder;public AdminStaffController(AppUserRepository users,PasswordEncoder encoder){this.users=users;this.encoder=encoder;}public record CreateStaff(@NotBlank @Size(max=120) String name,@Email @NotBlank String email,@Size(min=12,max=100) String temporaryPassword){}
 @PostMapping public ResponseEntity<?> create(@Valid @RequestBody CreateStaff r){String email=r.email().trim().toLowerCase();if(users.existsByEmailIgnoreCase(email))return ResponseEntity.status(409).body(Map.of("error","Email already registered"));AppUser u=users.save(new AppUser(r.name().trim(),email,encoder.encode(r.temporaryPassword()),"ADMIN"));return ResponseEntity.status(201).body(Map.of("id",u.getId(),"email",u.getEmail(),"role",u.getRole(),"message","Staff account created. Ask the staff member to change their temporary password."));}
 @GetMapping public Object list(){return users.findAll().stream().filter(u->u.getRole().equals("ADMIN")).map(u->Map.of("id",u.getId(),"name",u.getFullName(),"email",u.getEmail())).toList();}
}
